-- scripts/seed/steam_gifts_blog_post.sql
--
-- GENERATED by scripts/seed/build_steam_gifts_post.py — do not edit by hand.
-- Edit the markdown in that script and re-run it.
--
-- One guide post for the `steam-gifts` brand, in ru/en/uz, with 4 FAQ entries per
-- locale. The bodies were rendered through the API's own `markdown_to_html` +
-- `sanitize_body`, so what lands here is byte-for-byte what an editor pasting the
-- same markdown into the admin would have stored — no tag in it can be one the
-- fail-closed allowlist drops on read.
--
-- Inserted as a DRAFT on purpose. It is editorial copy on a public site: the owner
-- reads it and presses publish in the admin. `ck_blog_posts_brand_unless_draft`
-- allows a draft with no brand, but this one names its brand anyway so publishing
-- is the only step left.
--
-- Idempotent: keyed on the ru slug, rebuilt via delete-then-insert, one
-- transaction. Re-running replaces the post and drops any likes/views it had
-- collected (ON DELETE CASCADE) — harmless on a draft, worth knowing once it is
-- published.

BEGIN;

DELETE FROM blog_posts WHERE id IN (
    SELECT post_id FROM blog_post_translations
    WHERE locale = 'ru' AND slug = $x$kak-kupit-igru-v-steam-iz-uzbekistana$x$
);

WITH new_post AS (
    INSERT INTO blog_posts (id, kind, status, primary_brand_id, show_buy_card, pin_on_brand)
    SELECT gen_random_uuid(), 'guide', 'draft', b.id, true, false
    FROM brands b WHERE b.slug = 'steam-gifts'
    RETURNING id
),
tr AS (
    INSERT INTO blog_post_translations (post_id, locale, slug, title, excerpt, body_html, seo_title, seo_description)
    SELECT np.id, v.locale, v.slug, v.title, v.excerpt, v.body_html, v.seo_title, v.seo_description
    FROM new_post np, (VALUES
        ('ru', $x$kak-kupit-igru-v-steam-iz-uzbekistana$x$, $x$Как купить игру в Steam из Узбекистана$x$, $x$Узбекистанская карта в Steam не проходит, а цены для нашего региона редко самые низкие. Разбираем, как купить игру легально, за сумы и обычно дешевле, чем в самом Steam.$x$,
         $x$<p>Купить игру в Steam из Узбекистана — задача, у которой два разных препятствия, и
их обычно путают. Первое: узбекистанская карта в Steam чаще всего не проходит.
Второе, менее очевидное: даже когда оплата проходит, цена для нашего региона
редко оказывается самой низкой из возможных. Ниже — что с этим делать.</p>
<h2>Почему карта не проходит</h2>
<p>Steam принимает оплату не отовсюду и не любыми картами. Uzcard и Humo — это
локальные платёжные системы, за пределами страны они не работают, а
международные карты есть далеко не у всех. Отсюда все обходные пути, которыми
полон интернет: чужие аккаунты, VPN, «пополню за процент». Часть из них просто
неудобна, часть откровенно опасна — про это в конце.</p>
<h2>Цена в Steam зависит от региона</h2>
<p>Это ключевая вещь, про которую мало кто знает. У Steam нет одной цены на игру.
Издатель назначает разные цены для разных регионов, и разрыв бывает
двукратным. Цена для Узбекистана — не самая высокая в мире, но и не самая
низкая: соседние регионы часто дешевле.</p>
<p>Вот три реальных примера, снятых с витрины Steam в сентябре 2026 года:</p>
<table>
<thead>
<tr>
<th>Игра</th>
<th>Steam для Узбекистана</th>
<th>Наша цена</th>
</tr>
</thead>
<tbody>
<tr>
<td>West Escape</td>
<td>$0.99</td>
<td>$0.78</td>
</tr>
<tr>
<td>Age of Empires IV</td>
<td>$27.99</td>
<td>$21.20</td>
</tr>
<tr>
<td>Black Myth: Wukong</td>
<td>$59.99</td>
<td>$41.45</td>
</tr>
</tbody>
</table>
<p>Скажем сразу и честно: так бывает не всегда. Мы проверили 21 случайную игру из
каталога — дешевле оказались 17, примерно вровень 2, и на двух играх мы были
дороже. Медианная экономия среди выигрышных — около 15%, максимальная доходила
до 54%. Поэтому правильная формулировка — «обычно дешевле», а не «всегда»; цену
видно до оплаты, так что сравнить можно самому за десять секунд.</p>
<h2>Подарок Steam, а не ключ</h2>
<p>Способ, которым это работает легально, называется подарком Steam. Игра
покупается в том регионе, где она доступна, и отправляется на аккаунт
получателя штатным механизмом самого Steam — тем же, которым вы дарите игру
другу на день рождения.</p>
<p>Что из этого следует:</p>
<ul>
<li>Никаких ключей вводить не нужно. Игра появляется в библиотеке сама.</li>
<li>Пароль от аккаунта не нужен никому. Достаточно публичной ссылки на профиль.</li>
<li>Игра остаётся у получателя навсегда, как любая купленная.</li>
<li>Аккаунт остаётся ваш. Никакого «общего» или «арендованного» аккаунта.</li>
</ul>
<h2>Как купить: по шагам</h2>
<ol>
<li>Найдите игру в каталоге — поиском по названию.</li>
<li>Выберите издание, если их несколько, и регион аккаунта получателя.</li>
<li>Вставьте ссылку на профиль Steam. Ник и аватар покажутся сразу — это
страховка от опечатки в ссылке.</li>
<li>Оплатите картой Uzcard или Humo через Click, Payme или Uzum.</li>
<li>Дождитесь подарка. Обычно он приходит в течение часа.</li>
</ol>
<h2>Главная ошибка — регион аккаунта</h2>
<p>Подарок можно принять только в том регионе, для которого он куплен. Если
аккаунт получателя числится за другой страной, Steam просто не даст нажать
«Принять» — и это самая частая причина, по которой заказ застревает.</p>
<p>Проверяется за полминуты: Steam → «Об аккаунте» → строка «Страна». Это тот
самый регион, который нужно выбрать при оформлении. Если не совпадает — лучше
выяснить до оплаты, а не после.</p>
<h2>Если игра оказалась дополнением</h2>
<p>DLC работает только поверх основной игры. Подарить дополнение человеку, у
которого основной игры нет, технически можно — пользы от этого не будет
никакой, пока он не купит базовую версию. В карточке такие позиции помечены,
но на всякий случай стоит посмотреть.</p>
<h2>Про безопасность, коротко</h2>
<p>Единственное, что нужно для подарка, — ссылка на профиль. Она публичная, её
видно любому.</p>
<p>Никто и никогда не должен просить у вас пароль от Steam, код из
Steam Guard или доступ к почте ради покупки игры. Если просят — это не
магазин, а кража аккаунта, и никакая цена этого не стоит. Правило простое и
не знает исключений.</p>$x$,
         $x$Как купить игру в Steam из Узбекистана за сумы — YuPay$x$, $x$Пошаговая инструкция: как купить игру в Steam из Узбекистана, оплатить сумами картой Uzcard или Humo и не ошибиться с регионом аккаунта. С реальным сравнением цен.$x$),
        ('en', $x$how-to-buy-steam-games-from-uzbekistan$x$, $x$How to buy Steam games from Uzbekistan$x$, $x$An Uzbek card usually will not go through on Steam, and the Uzbekistan price is rarely the lowest one. Here is how to buy a game legally, in sum, and usually cheaper.$x$,
         $x$<p>Buying a Steam game from Uzbekistan runs into two separate obstacles, and they
are usually confused with each other. First: an Uzbek card will most often not
go through on Steam. Second, and less obvious: even when payment does go
through, the price set for our region is rarely the lowest one available. Here
is what to do about both.</p>
<h2>Why the card is declined</h2>
<p>Steam does not accept payment from everywhere or from every card. Uzcard and
Humo are domestic payment systems and do not work abroad, and international
cards are far from universal here. That is where the workarounds the internet
is full of come from: borrowed accounts, VPNs, &quot;I'll top you up for a cut&quot;.
Some of those are merely inconvenient. Some are outright dangerous — more on
that at the end.</p>
<h2>A Steam price depends on the region</h2>
<p>This is the part few people know. Steam does not have one price per game. The
publisher sets different prices for different regions, and the gap can be
twofold. The Uzbekistan price is not the highest in the world, but it is not
the lowest either: neighbouring regions are often cheaper.</p>
<p>Three real examples, read off Steam's own storefront in September 2026:</p>
<table>
<thead>
<tr>
<th>Game</th>
<th>Steam for Uzbekistan</th>
<th>Our price</th>
</tr>
</thead>
<tbody>
<tr>
<td>West Escape</td>
<td>$0.99</td>
<td>$0.78</td>
</tr>
<tr>
<td>Age of Empires IV</td>
<td>$27.99</td>
<td>$21.20</td>
</tr>
<tr>
<td>Black Myth: Wukong</td>
<td>$59.99</td>
<td>$41.45</td>
</tr>
</tbody>
</table>
<p>To be straight about it: this is not always the case. We checked 21 randomly
picked titles from the catalogue — 17 came out cheaper, 2 were roughly level,
and on 2 of them we were dearer. The median saving among the wins was about
15%, the best reached 54%. So the honest wording is &quot;usually cheaper&quot;, not
&quot;always&quot;; the price is shown before you pay, so checking takes ten seconds.</p>
<h2>A Steam gift, not a key</h2>
<p>The mechanism that makes this legal is the Steam gift. The game is bought in a
region where it is available and sent to the recipient's account through
Steam's own gifting system — the same one you use for a friend's birthday.</p>
<p>What follows from that:</p>
<ul>
<li>There is no key to enter anywhere. The game simply appears in the library.</li>
<li>Nobody needs your account password. A public profile link is enough.</li>
<li>The game stays with the recipient for good, like any other purchase.</li>
<li>The account stays yours. No shared account, no rented account.</li>
</ul>
<h2>How to buy, step by step</h2>
<ol>
<li>Find the game in the catalogue by name.</li>
<li>Pick the edition, if there is more than one, and the recipient's account
region.</li>
<li>Paste the Steam profile link. The nickname and avatar appear immediately —
your insurance against a mistyped link.</li>
<li>Pay with an Uzcard or Humo card via Click, Payme or Uzum.</li>
<li>Wait for the gift. It usually arrives within an hour.</li>
</ol>
<h2>The one mistake that matters: account region</h2>
<p>A gift can only be accepted in the region it was bought for. If the
recipient's account belongs to a different country, Steam will simply not let
them click &quot;Accept&quot; — and that is the most common reason an order stalls.</p>
<p>Checking takes half a minute: Steam, then &quot;Account details&quot;, then the
&quot;Country&quot; line. That is the region to pick at checkout. If it does not match,
find out before paying rather than after.</p>
<h2>If the title turns out to be DLC</h2>
<p>DLC only works on top of the base game. You can technically gift an add-on to
someone who does not own the game, but it will do nothing at all until they
buy the base version. Such entries are marked on the card, but it is worth a
glance either way.</p>
<h2>On safety, briefly</h2>
<p>The only thing a gift needs is a profile link. It is public; anyone can see
it.</p>
<p>Nobody should ever ask you for your Steam password, a Steam Guard code, or
access to your email in order to buy you a game. If they do, that is not a
shop, it is account theft, and no price is worth it. The rule is simple and
has no exceptions.</p>$x$,
