INSERT INTO blog_post_faqs (id, post_id, locale, sort_order, question, answer)
SELECT gen_random_uuid(), np.id, v.locale, v.sort_order, v.question, v.answer
FROM new_post np, (VALUES
    (1, 'ru', $x$Можно ли оплатить Steam узбекистанской картой?$x$,
     $x$Напрямую в Steam — чаще всего нет: Uzcard и Humo за пределами страны не работают. У нас оплата идёт в сумах этими же картами через Click, Payme или Uzum, а игра приходит на аккаунт подарком Steam.$x$),
    (1, 'en', $x$Can I pay Steam with an Uzbek card?$x$,
     $x$Directly on Steam, usually not: Uzcard and Humo do not work outside the country. Here you pay in sum with those same cards via Click, Payme or Uzum, and the game reaches the account as a Steam gift.$x$),
    (1, 'uz', $x$Steamga oʻzbek kartasi bilan toʻlash mumkinmi?$x$,
     $x$Toʻgʻridan-toʻgʻri Steamda — koʻpincha yoʻq: Uzcard va Humo mamlakatdan tashqarida ishlamaydi. Bizda toʻlov aynan shu kartalar bilan Click, Payme yoki Uzum orqali soʻmda amalga oshadi, oʻyin esa akkauntga Steam sovgʻasi sifatida keladi.$x$),
    (2, 'ru', $x$Подарок Steam — это законно?$x$,
     $x$Да. Подарок — штатная функция самого Steam: так игру дарят другу на день рождения. Аккаунт остаётся ваш, никакие правила Steam при этом не нарушаются, а игра остаётся в библиотеке навсегда.$x$),
    (2, 'en', $x$Is a Steam gift legitimate?$x$,
     $x$Yes. Gifting is a built-in Steam feature — it is how you give a friend a game for their birthday. The account stays yours, no Steam rule is broken, and the game stays in the library for good.$x$),
    (2, 'uz', $x$Steam sovgʻasi qonuniymi?$x$,
     $x$Ha. Sovgʻa — Steamning oʻz funksiyasi: doʻstga tugʻilgan kunga oʻyin shunday sovgʻa qilinadi. Akkaunt sizniki boʻlib qoladi, Steam qoidalari buzilmaydi, oʻyin esa kutubxonada butunlay qoladi.$x$),
    (3, 'ru', $x$Что будет, если игра уже есть у получателя?$x$,
     $x$Steam не даст принять такой подарок — он останется в списке ожидающих. Поэтому перед покупкой стоит уточнить у получателя, нет ли игры в библиотеке: это единственная проверка, которую мы сделать за вас не можем.$x$),
    (3, 'en', $x$What if the recipient already owns the game?$x$,
     $x$Steam will not let them accept such a gift — it stays in their pending list. So it is worth asking the recipient whether the game is already in their library: that is the one check we cannot make for you.$x$),
    (3, 'uz', $x$Agar oʻyin qabul qiluvchida allaqachon boʻlsa nima boʻladi?$x$,
     $x$Steam bunday sovgʻani qabul qildirmaydi — u kutilayotganlar roʻyxatida qoladi. Shuning uchun sotib olishdan oldin qabul qiluvchidan oʻyin kutubxonasida yoʻqligini soʻrash kerak: bu biz siz uchun qila olmaydigan yagona tekshiruv.$x$),
    (4, 'ru', $x$Можно ли купить игру себе, а не в подарок?$x$,
     $x$Да, и это самый частый случай. Просто укажите ссылку на свой собственный профиль Steam — подарок придёт вам, и игра встанет в вашу библиотеку.$x$),
    (4, 'en', $x$Can I buy a game for myself rather than as a gift?$x$,
     $x$Yes, and that is the common case. Just give the link to your own Steam profile — the gift comes to you and the game lands in your library.$x$),
    (4, 'uz', $x$Oʻyinni sovgʻa sifatida emas, oʻzimga sotib olsam boʻladimi?$x$,
     $x$Ha, va bu eng koʻp uchraydigan holat. Shunchaki oʻz Steam profilingizga havolani koʻrsating — sovgʻa sizga keladi va oʻyin kutubxonangizga tushadi.$x$)
) AS v(sort_order, locale, question, answer);

COMMIT;
